def calc(expr: str) -> int | str:
    values = []
    operators = []
    precedence = {"+": 1, "-": 1, "*": 2, "/": 2, "%": 2, "neg": 3, "^": 4}

    def apply():
        op = operators.pop()
        if op == "neg":
            values.append(-values.pop())
            return

        b = values.pop()
        a = values.pop()

        if op == "+":
            values.append(a + b)
        elif op == "-":
            values.append(a - b)
        elif op == "*":
            values.append(a * b)
        elif op == "^":
            if b < 0:
                raise ValueError
            values.append(pow(a, b))
        else:
            if b == 0:
                raise ValueError
            quotient = abs(a) // abs(b)
            if (a < 0) != (b < 0):
                quotient = -quotient
            values.append(quotient if op == "/" else a - b * quotient)

    try:
        i = 0
        expecting_operand = True

        while i < len(expr):
            char = expr[i]

            if char == " ":
                i += 1
            elif "0" <= char <= "9":
                number = 0
                while i < len(expr) and "0" <= expr[i] <= "9":
                    number = number * 10 + ord(expr[i]) - ord("0")
                    i += 1
                values.append(number)
                expecting_operand = False
            elif char == "(":
                operators.append(char)
                expecting_operand = True
                i += 1
            elif char == ")":
                while operators[-1] != "(":
                    apply()
                operators.pop()
                expecting_operand = False
                i += 1
            elif char == "-" and expecting_operand:
                operators.append("neg")
                i += 1
            else:
                while (
                    operators
                    and operators[-1] != "("
                    and (
                        precedence[operators[-1]] > precedence[char]
                        or (
                            precedence[operators[-1]] == precedence[char]
                            and char != "^"
                        )
                    )
                ):
                    apply()
                operators.append(char)
                expecting_operand = True
                i += 1

        while operators:
            apply()

        return values[0]
    except ValueError:
        return "error"
